begin;
create function pg_temp.review_claim(uid uuid) returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','aal','aal1')::text,true);end$$;
create function pg_temp.review_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'REVIEW ASSERT: %',label;end if;end$$;
insert into auth.users(id,email,email_confirmed_at) values('95000000-1000-4000-8000-000000000001','review-seller@example.invalid',now()),('95000000-1000-4000-8000-000000000002','review-buyer@example.invalid',now()),('95000000-1000-4000-8000-000000000003','review-other@example.invalid',now());
do $$declare seller uuid:='95000000-1000-4000-8000-000000000001';buyer uuid:='95000000-1000-4000-8000-000000000002';otherid uuid:='95000000-1000-4000-8000-000000000003';sid uuid;pid uuid;oid uuid;sampleid uuid;pic text;state jsonb;item jsonb;begin
 perform pg_temp.review_claim(seller);perform public.th_api('snapshot');perform pg_temp.review_claim(buyer);perform public.th_api('snapshot');perform pg_temp.review_claim(otherid);perform public.th_api('snapshot');
 select id into sid from public.th_shops where user_id=seller;update public.th_shops set status='verified' where id=sid;
 pic:=seller::text||'/95000000-1000-4000-8000-000000000099.png';insert into public.th_uploads(path,user_id) values(pic,seller);
 insert into public.th_products(shop_id,title,description,category,condition,location,image_path,price,mode) values(sid,'Review test product','Review security test item','home','สภาพดี','Bangkok',pic,100,'fixed') returning id into pid;
 insert into public.th_orders(user_id,total,request_key,payload) values(buyer,100,'review-order-01','{}') returning id into oid;
 insert into public.th_order_items(order_id,product_id,shop_id,title,price) values(oid,pid,sid,'Review test product',100);
 perform pg_temp.review_claim(buyer);begin perform public.th_api('product_review',jsonb_build_object('orderId',oid,'productId',pid,'rating',5,'comment','ก่อนรับสินค้า'));raise exception 'Premature review accepted';exception when sqlstate 'PT403' then null;end;
 insert into public.th_order_handoffs(order_id,shop_id,buyer_confirmed_at,seller_confirmed_at,completed_at) values(oid,sid,public.th_now(),public.th_now(),public.th_now());
 perform pg_temp.review_claim(otherid);begin perform public.th_api('product_review',jsonb_build_object('orderId',oid,'productId',pid,'rating',5,'comment','ไม่ได้ซื้อ'));raise exception 'Other user accepted';exception when sqlstate 'PT403' then null;end;
 perform pg_temp.review_claim(buyer);begin perform public.th_api('product_review',jsonb_build_object('orderId',oid,'productId',pid,'rating',6,'comment','ผิด'));raise exception 'Invalid rating accepted';exception when sqlstate 'PT400' then null;end;
 perform public.th_api('product_review',jsonb_build_object('orderId',oid,'productId',pid,'rating',4,'comment','สินค้าตรงรายละเอียด'));
 begin perform public.th_api('product_review',jsonb_build_object('orderId',oid,'productId',pid,'rating',5,'comment','ซ้ำ'));raise exception 'Duplicate accepted';exception when sqlstate 'PT409' then null;end;
 state:=public.th_api('snapshot');perform pg_temp.review_assert(jsonb_array_length(state->'myReviews')=1,'owner sees own review');
 insert into public.th_sample_orders(user_id,total,status,request_key,payload,items,completed_at) values(buyer,100,'completed','review-sample-order','{}','[{"id":"p15","title":"sample","price":100}]',public.th_now()) returning id into sampleid;
 perform public.th_api('product_review',jsonb_build_object('orderId',sampleid,'productId','p15','rating',5,'comment','ทดลองระบบ'));
 perform set_config('request.jwt.claims','{}',true);state:=public.th_api('snapshot');
 select value into item from jsonb_array_elements(state->'products') where value->>'id'=pid::text;
 perform pg_temp.review_assert((item->>'reviewCount')::int=1 and (item->>'ratingAverage')::numeric=4 and item#>>'{reviews,0,comment}'='สินค้าตรงรายละเอียด','public product summary');
 select value into item from jsonb_array_elements(state->'products') where value->>'id'='p15';perform pg_temp.review_assert(item#>'{reviews,0,isDemo}'='true'::jsonb,'sample review marked demo');
 select value into item from jsonb_array_elements(state->'stores') where value->>'id'=sid::text;perform pg_temp.review_assert((item->>'reviewCount')::int=1 and (item->>'ratingAverage')::numeric=4,'seller rating excludes sample');
 begin perform public.th_api('product_review',jsonb_build_object('orderId',oid,'productId',pid,'rating',5,'comment','guest'));raise exception 'Guest accepted';exception when sqlstate 'PT401' then null;end;
end$$;
select 'verified buyer product reviews, sample labeling and access control: PASS' as result;
rollback;
